export const getExplainUrl = (userId: string,
    params: ExplainParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/v1/users/${userId}/effective-access/explain?${stringifiedParams}` : `/v1/users/${userId}/effective-access/explain`
}

export const explain = async (userId: string,
    params: ExplainParams, options?: Parameters<typeof apiFetch>[1]): Promise<Explanation> => {

  return apiFetch<Explanation>(getExplainUrl(userId,params),
  {
    ...options,
    method: 'GET'


  }
);}



